// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 timeOffset, uint256 blockNumber) public {
        // Bound block number to a realistic range
        uint256 blockNum = bound(blockNumber, 1, 1000);
        // Bound time offset to ensure timestamp > pastBlockTime
        uint256 time = bound(timeOffset, 1, 10000);
        vm.warp(block.timestamp + time);
        vm.roll(blockNum);

        uint256 prevTime = c.pastBlockTime();

        // Send 10 ether to trigger fallback
        vm.deal(address(this), 10 ether);
        (bool success, ) = address(c).call{value: 10 ether}("");

        uint256 newTime = c.pastBlockTime();

        // General rule: if call succeeded (timestamp > prevTime), then pastBlockTime must equal block.timestamp
        if (success) {
            assertTrue(newTime == block.timestamp);
        } else {
            // If reverted, pastBlockTime must remain unchanged
            assertTrue(newTime == prevTime);
        }
    }
}

